"Claude used blocks this page doesn't have ({blocks}), so nothing was loaded. Try again, or describe it differently.":"Claude ܐܫܬܡܫ ܒܠܒܢܐ ܕܠܝܬ ܒܕܦܐ ܗܢܐ ({blocks}), ܘܡܬܘܠ ܗܢܐ ܡܕܡ ܠܐ ܐܬܥܢ. ܢܣܝ ܬܘܒ, ܐܘ ܦܫܗܩ ܐܚܪܝܐܝܬ.",
