"Drag blocks from the categories; drag a block back onto them to delete it. Round slots take values, hexagon slots take yes/no conditions.":"ܓܪܘܪ ܠܒܢܐ ܡܢ ܓܢܣܐ; ܓܪܘܪ ܠܒܢܬܐ ܠܗܘܢ ܠܡܫܩܠܗ. ܐܬܪܘܬܐ ܥܓܝܠܐ ܡܩܒܠܝܢ ܫܘܚܠܦܐ, ܐܬܪܘܬܐ ܕܫܬ ܙܘܝܢ ܡܩܒܠܝܢ ܬܢܘܬܐ ܕܐܝܢ ܐܘ ܠܐ.",
