"Each one is a complete program. Load it, press Run, then change the words on the blocks to make it yours. Your current program is replaced, so save it first in Programs if you want to keep it.":"ܟܘܠ ܚܕ ܛܘܟܣܐ ܓܡܝܪܐ ܗܘ. ܐܥܢ ܠܗ, ܕܘܫ 'ܪܗܛ', ܘܒܬܪ ܫܢܝ ܡܠܐ ܕܥܠ ܠܒܢܐ ܠܡܥܒܕܗ ܕܝܠܟ. ܛܘܟܣܟ ܕܗܫܐ ܡܬܚܠܦ, ܡܬܘܠ ܗܢܐ ܢܛܘܪ ܠܗ ܩܕܡ ܒܛܘܟܣܐ ܐܢ ܨܒܐ ܐܢܬ ܠܡܢܛܪܗ.",
