"Even after carrying on, the reply was still too long, so it stops part-way. It's kept as it is, marked best effort. Ask for something shorter, or split the job into smaller steps.":"ܐܦܢ ܒܬܪ ܕܐܙܠ, ܦܬܓܡܐ ܥܕܟܝܠ ܢܓܝܪ ܝܬܝܪ ܗܘܐ, ܘܡܬܘܠ ܗܢܐ ܦܣܩ ܒܦܠܓܗ. ܡܬܢܛܪ ܐܝܟܢ ܕܐܝܬܘ, ܪܫܝܡ ܐܟ ܥܒܕܐ ܫܦܝܪܐ ܕܡܫܟܚ. ܫܐܠ ܡܕܡ ܙܥܘܪ ܝܬܝܪ, ܐܘ ܦܠܓ ܥܒܕܐ ܠܕܪܓܐ ܙܥܘܪܐ.",
