"Import undone. Your previous program is back.":"ܥܠܘܬܐ ܐܬܗܦܟܬ. ܛܘܟܣܟ ܩܕܡܝܐ ܗܦܟ.",
"In this page, the Home Assistant blocks use a <b>sample house</b>, so you can build and test safely. Change a state below (press Enter) to try your 'when … changes' scripts. Exported Python connects to your real Home Assistant: set HA_URL and HA_TOKEN (a long-lived access token from your Home Assistant profile, under Security).":"ܒܕܦܐ ܗܢܐ, ܠܒܢܐ ܕ-Home Assistant ܡܫܬܡܫܝܢ ܒ<b>ܒܝܬܐ ܕܛܘܦܣܐ</b>, ܕܬܫܟܚ ܠܡܒܢܐ ܘܠܡܢܣܝܘ ܕܠܐ ܕܚܠܬܐ. ܫܢܝ ܐܝܟܢܘܬܐ ܠܬܚܬ (ܕܘܫ Enter) ܠܢܣܝܢܐ ܕܦܣܩܬܟ ܕ'ܟܕ … ܡܬܚܠܦ'. Python ܕܢܦܩܐ ܡܬܚܒܪ ܠ-Home Assistant ܫܪܝܪܐ ܕܝܠܟ: ܣܝܡ HA_URL ܘ-HA_TOKEN (ܐܬܐ ܢܓܝܪܐ ܡܢ ܦܪܣܘܦܐ ܕ-Home Assistant ܕܝܠܟ, ܬܚܬ Security).",
"In your program, the arrow keys move between blocks, their slots and their fields. <b>Enter</b> on a field lets you type in it or choose, and <b>W</b> brings you back to your program.":"ܒܛܘܟܣܟ, ܩܠܝܕܐ ܕܣܘܦܐ ܐܙܠܝܢ ܒܝܬ ܠܒܢܐ, ܐܬܪܘܬܗܘܢ ܘܚܩܠܝܗܘܢ. <b>Enter</b> ܥܠ ܚܩܠܐ ܫܒܩ ܠܟ ܕܬܟܬܘܒ ܒܝܗ ܐܘ ܕܬܓܒܐ, ܘ<b>W</b> ܡܗܦܟ ܠܟ ܠܛܘܟܣܟ.",
"Input":"ܡܥܠܐ",
