"Instructions for Claude":"ܦܘܩܕܢܐ ܠ-Claude",
"It asked for {name} with the same input three times in a row. The draft holds its last result.":"ܫܐܠ l{name} ܥܡ ܚܕ ܡܥܠܐ ܬܠܬܐ ܙܒܢܝܢ ܐܚܕܕܐ. ܪܘܫܡܐ ܐܚܕ ܦܝܪܐ ܚܪܝܐ.",
