"It can {things}.":"ܡܫܟܚ {things}.",
"It doesn't yet meet the criteria.":"ܥܕܟܝܠ ܠܐ ܫܘܐ ܠܢܡܘܣܐ.",
"It only uses your models: it doesn't connect to anything else.":"ܡܫܬܡܫܐ ܒܠܚܘܕ ܒܕܡܘܬܟ: ܠܐ ܡܬܚܒܪ ܠܡܕܡ ܐܚܪܝܢܐ.",
"It replied with a tool on its last step, so it stopped there.":"ܥܢܐ ܥܡ ܡܢܐ ܒܕܪܓܐ ܚܪܝܬܐ, ܘܡܬܘܠ ܗܢܐ ܦܣܩ ܬܡܢ.",
"It replied with “{name}”, which isn't one of its tools.":"ܥܢܐ ܥܡ “{name}”, ܕܠܐ ܗܘܐ ܡܢ ܡܢܘ.",
"It said it was done, but its answer was empty.":"ܐܡܪ ܕܫܠܡ, ܐܠܐ ܦܬܓܡܗ ܣܪܩ ܗܘܐ.",
"It used all {n} steps without a final answer. The draft holds its last result.":"ܐܫܬܡܫ ܒܟܘܠܗܘܢ {n} ܕܪܓܐ ܕܠܐ ܦܬܓܡܐ ܚܪܝܐ. ܪܘܫܡܐ ܐܚܕ ܦܝܪܐ ܚܪܝܐ.",
"It was saved with older blocks and has been brought up to date (block format {from} to {to}).":"ܐܬܢܛܪ ܥܡ ܠܒܢܐ ܥܬܝܩܐ ܘܐܬܚܕܬ (ܐܣܟܝܡܐ ܕܠܒܢܐ {from} l{to}).",
"Its Python was exported with a runtime from before versions were numbered; this page has runtime {ours}. Export it again to give the Python program the new runtime (CHANGELOG.md says what changed).":"Python ܕܝܠܗ ܢܦܩ ܥܡ ܛܘܟܣܐ ܕܪܗܛܐ ܡܢ ܩܕܡ ܕܢܘܣܚܐ ܢܬܡܢܘܢ; ܕܦܐ ܗܢܐ ܐܝܬ ܠܗ ܛܘܟܣܐ ܕܪܗܛܐ {ours}. ܐܦܩ ܠܗ ܬܘܒ ܠܡܬܠ ܠܛܘܟܣܐ ܕ-Python ܛܘܟܣܐ ܕܪܗܛܐ ܚܕܬܐ (CHANGELOG.md ܐܡܪ ܡܐ ܕܫܬܚܠܦ).",
"Its Python was exported with runtime {theirs}; this page has runtime {ours}. Export it again to give the Python program the new runtime (CHANGELOG.md says what changed).":"Python ܕܝܠܗ ܢܦܩ ܥܡ ܛܘܟܣܐ ܕܪܗܛܐ {theirs}; ܕܦܐ ܗܢܐ ܐܝܬ ܠܗ ܛܘܟܣܐ ܕܪܗܛܐ {ours}. ܐܦܩ ܠܗ ܬܘܒ ܠܡܬܠ ܠܛܘܟܣܐ ܕ-Python ܛܘܟܣܐ ܕܪܗܛܐ ܚܕܬܐ (CHANGELOG.md ܐܡܪ ܡܐ ܕܫܬܚܠܦ).",
