"You can build programs with the keyboard alone. Press <b>Tab</b> until you reach the block editor, then:":"ܡܫܟܚ ܐܢܬ ܕܬܒܢܐ ܛܘܟܣܐ ܥܡ ܠܘܚܐ ܕܩܠܝܕܐ ܒܠܚܘܕ. ܕܘܫ <b>Tab</b> ܥܕܡܐ ܕܡܛܐ ܐܢܬ ܠܡܣܕܪܢܐ ܕܠܒܢܐ, ܘܒܬܪ:",
