"{who} can't be reached from this page, so Claude answers in its place. Export to Python to use {who} itself.":"{who} ܠܐ ܡܫܟܚ ܕܢܬܡܛܐ ܡܢ ܗܢܐ ܕܦܐ, ܘܡܬܘܠ ܗܢܐ Claude ܥܢܐ ܚܠܦܗ. ܐܦܩ ܠ-Python ܠܡܫܬܡܫܘ b{who} ܓܢܗ.",
"{who} has no key on this page, and Claude can't stand in for it here. Add a key for it with “Add another key” at the top, or choose a model you have a key for.":"l{who} ܠܝܬ ܩܠܝܕܐ ܒܗܢܐ ܕܦܐ, ܘ-Claude ܠܐ ܡܫܟܚ ܕܢܩܘܡ ܚܠܦܗ ܗܪܟܐ. ܐܘܣܦ ܠܗ ܩܠܝܕܐ ܥܡ “ܐܘܣܦ ܩܠܝܕܐ ܐܚܪܝܢܐ” ܠܥܠ, ܐܘ ܓܒܝ ܕܡܘܬܐ ܕܐܝܬ ܠܟ ܩܠܝܕܗ.",
"{who} is having trouble right now ({problem}). Run again in a moment.":"{who} ܐܝܬ ܠܗ ܥܩܬܐ ܗܫܐ ({problem}). ܪܗܛ ܬܘܒ ܒܬܪ ܩܠܝܠ.",
"{who} refused the request ({problem}).":"{who} ܠܥܙ ܠܒܥܘܬܐ ({problem}).",
"{who} refused your API key. Check it, or forget it and enter it again.":"{who} ܠܥܙ ܠܩܠܝܕܐ ܕ-API ܕܝܠܟ. ܒܚܢ ܠܗ, ܐܘ ܛܥܝ ܠܗ ܘܟܬܘܒ ܠܗ ܬܘܒ.",
"{who} returned nothing for this step. Simplify it and try again.":"{who} ܠܐ ܗܦܟ ܡܕܡ ܠܗܕܐ ܕܪܓܐ. ܦܫܘܛ ܠܗ ܘܢܣܝ ܬܘܒ.",
"{who} says this key's account has no credit left: {problem}":"{who} ܐܡܪ ܕܚܘܫܒܢܐ ܕܗܢܐ ܩܠܝܕܐ ܠܝܬ ܠܗ ܟܣܦܐ: {problem}",
"{who} says too many requests right now. Wait a minute and run again.":"{who} ܐܡܪ ܕܣܓܝܐܢ ܒܥܘܬܐ ܗܫܐ. ܣܟܐ ܩܛܝܢܐ ܘܪܗܛ ܬܘܒ.",
"~{n} tokens":"~{n} ܐܬܘܬܐ",
"“{hhmm}” isn't a time like 09:00.":"“{hhmm}” ܠܐ ܗܘܐ ܫܥܬܐ ܐܟ 09:00.",
"“{kind}” isn't a type the agent knows. Use text, number, yes/no, list or any (for “{name}”).":"“{kind}” ܠܐ ܗܘܐ ܓܢܣܐ ܕܫܠܝܚܐ ܝܕܥ. ܐܛܥܢ text, number, yes/no, list ܐܘ any (l“{name}”).",
"“{name}” can't run while other scripts are running at the same time. Run it from a script that runs on its own (not alongside a broadcast).":"“{name}” ܠܐ ܡܫܟܚ ܕܢܪܗܛ ܟܕ ܦܣܩܬܐ ܐܚܪܢܝܬܐ ܪܗܛܢ ܒܚܕ ܙܒܢܐ. ܪܗܛ ܠܗ ܡܢ ܦܣܩܬܐ ܕܪܗܛܐ ܒܠܚܘܕܝܗ (ܠܐ ܠܘܬ ܫܘܕܪܐ).",
"“{repo}” isn't a GitHub project. Use owner/name, like octocat/hello-world.":"“{repo}” ܠܐ ܗܘܐ ܥܒܕܐ ܕ-GitHub. ܐܛܥܢ owner/name, ܐܟ octocat/hello-world.",
"“{shown}” isn't a real date.":"“{shown}” ܠܐ ܗܘܐ ܝܘܡܐ ܫܪܝܪܐ.",
"“{shown}” isn't a time.":"“{shown}” ܠܐ ܗܘܐ ܫܥܬܐ.",
"“{svc}” isn't a service name. Use domain.service, for example light.turn_off.":"“{svc}” ܠܐ ܗܘܐ ܫܡܐ ܕܫܡܫܘܬܐ. ܐܛܥܢ domain.service, ܐܟ light.turn_off.",
"“{text}” isn't a day. Use today, tomorrow, a weekday or YYYY-MM-DD.":"“{text}” ܠܐ ܗܘܐ ܝܘܡܐ. ܐܛܥܢ today, tomorrow, ܝܘܡܐ ܕܫܒܬܐ ܐܘ YYYY-MM-DD.",
"“{to}” isn't an email address.":"“{to}” ܠܐ ܗܘܐ ܥܠܩܬܐ ܕܐܓܪܬܐ.",
"“{value}” isn't a number.":"“{value}” ܠܐ ܗܘܐ ܡܢܝܢܐ.",
"“{value}” isn't on or off.":"“{value}” ܠܐ ܗܘܐ on ܐܘ off.",
"A Coinbase order is buy or sell.":"ܦܘܩܕܢܐ ܕ-Coinbase ܙܒܢܐ ܐܘ ܙܘܒܢܐ ܐܝܬܘ.",
