"Coinbase order cancelled":"ܦܘܩܕܢܐ ܕ-Coinbase ܐܬܒܛܠ",
"Coinbase order placed":"ܦܘܩܕܢܐ ܕ-Coinbase ܐܬܝܗܒ",
"Coinbase wouldn't place that order: {why}.":"Coinbase ܠܐ ܥܒܕܐ ܦܘܩܕܢܐ ܗܢܐ: {why}.",
"Coinbase: {why}.":"Coinbase: {why}.",
"Only spot trading pairs, like BTC-GBP, are offered here.":"ܗܪܟܐ ܐܝܬ ܒܠܚܘܕ ܙܘܓܐ ܕܙܒܢܐ ܡܚܕܐ, ܐܟ BTC-GBP.",
"The amount should be a number above 0, like 50.":"ܡܢܝܢܐ ܢܗܘܐ ܝܬܝܪ ܡܢ 0, ܐܟ 50.",
"Which Coinbase order? Give its id, from 'Coinbase open orders'.":"ܐܝܢܐ ܦܘܩܕܢܐ ܕ-Coinbase? ܗܒ id ܕܝܠܗ, ܡܢ „ܦܘܩܕܢܐ ܦܬܝܚܐ ܕ-Coinbase”.",
"not found":"ܠܐ ܐܫܬܟܚ",
"{n} assets":"{n} ܩܢܝܢܐ",
"“{product}” isn't a Coinbase trading pair. Use one like BTC-GBP.":"„{product}” ܠܘ ܙܘܓܐ ܕ-Coinbase ܐܝܬܘ. ܫܩܘܠ ܚܕ ܐܟ BTC-GBP.",
"Coinbase account":"ܚܘܫܒܢܐ ܕ-Coinbase",
"sample account":"ܚܘܫܒܢܐ ܕܛܘܦܣܐ",
"trade on your Coinbase account with real money (asking you before every order)":"ܙܒܘܢ ܘܙܒܢ ܒܚܘܫܒܢܟ ܕ-Coinbase ܒܟܣܦܐ ܫܪܝܪܐ (ܫܐܠ ܠܟ ܩܕܡ ܟܘܠ ܦܘܩܕܢܐ)",
"read your Coinbase balances and orders, and market prices":"ܩܪܝ ܫܪܟܢܝܟ ܘܦܘܩܕܢܝܟ ܕ-Coinbase, ܘܛܝܡܐ ܕܫܘܩܐ",
"MikroTik":"MikroTik",
"MikroTik ports":"ܬܪܥܐ ܕ-MikroTik",
"{n} ports":"{n} ܬܪܥܐ",
