"read your MikroTik router or switch: its ports, modules, health and log":"ܩܪܝ ܡܫܚܠܦܢܟ ܕ-MikroTik: ܬܪܥܘ, ܡܢܘܬܗ, ܫܠܡܗ ܘܟܛܒܗ",
"UniFi":"UniFi",
"UniFi clients":"ܐܟܣܢܝܐ ܕ-UniFi",
