"ha_mesh":{"title":"ܨܒܘܪ ܪܫܬܐ ܕ-Zigbee","desc":"ܡܢܝ ܐܘܪܓܢܝܟ ܕ-Zigbee ܐܘ ܕ-Z-Wave ܘܐܝܟܐ ܐܢܘܢ; ܩܒܠ ܡܠܟܘܬܐ ܥܠ ܣܡܬܐ ܕܐܘܪܓܢܐ ܡܥܒܪܢܐ ܕܪܫܬܐ ܬܗܘܐ ܫܪܝܪܬܐ.","tip":"ܐܡܪ ܐܝܢܐ ܐܘܪܓܢܐ ܡܢ ܚܝܠܐ ܕܒܝܬܐ: ܫܡܫܐ ܘܫܪܓܐ ܒܥܝܕܐ ܥܒܕܝܢ ܐܟ ܡܥܒܪܢܐ."},
