"ha_morning":{"title":"ܡܟܡܘܬܐ ܕܨܦܪܐ","desc":"ܒ-07:15 (ܐܘ ܟܕ ܕܝܫ ܐܢܬ 'ܪܗܛ'): ܐܐܪ, ܡܢܐ ܕܛܢܦܘܬܐ, ܩܠܢܕܪܐ, ܡܢ ܒܝܬܐ ܘܡܕܡ ܕܐܫܬܒܩ ܦܩܝܚ ܒܠܝܠܝܐ, ܒܦܣܘܩܐ ܚܕ ܚܒܝܒܐ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܫܢܝ ܫܥܬܐ ܒܠܒܢܬܐ ܨܗܘܒܬܐ, ܐܘ ܐܡܪ ܠܗ ܥܠ ܢܓܘܢܐ."},
"ha_goodnight":{"title":"ܒܚܘܚܐ ܕܠܝܠܝܐ ܛܒܐ","desc":"ܒܚܢ ܬܪܥܐ, ܟܘܐ, ܩܠܝܕܐ ܘܫܪܓܐ, ܡܢܐ ܟܘܠ ܡܕܡ ܕܠܐ ܫܪܝܪ ܒܡܠܐ ܦܫܝܛܬܐ, ܘܒܬܪ ܫܐܠ ܠܡܩܦܠ ܘܠܡܥܒܪܐ ܫܪܓܐ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܪܗܛ ܠܗ ܡܢ ܬܠܦܘܢܟ ܒܙܒܢܐ ܕܫܢܐ, ܐܘ ܐܘܣܦ ܙܒܢܐ ܕ-22:30."},
"ha_leaving":{"title":"ܡܦܩܬܐ ܡܢ ܒܝܬܐ","desc":"ܟܕ ܐܢܫܐ ܚܪܝܐ ܢܦܩ, ܡܥܒܪ ܟܘܠ ܫܪܓܐ ܕܥܕܟܝܠ ܢܗܝܪ ܘܐܡܪ ܠܟ ܡܢܐ ܡܥܒܪ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܒܓܒܐ ܕ-Home Assistant, ܫܢܝ person.alex ܠ-not_home ܠܢܣܝܢܐ."},
"ha_welcome":{"title":"ܡܟܡܘܬܐ ܕܐܬܝܬܐ ܠܒܝܬܐ","desc":"ܟܕ ܐܬܐ ܐܢܬ ܠܒܝܬܐ, ܡܟܡܡ ܡܐ ܕܗܘܐ ܟܕ ܠܒܪ ܗܘܝܬ: ܬܪܥܐ, ܙܘܥܐ ܘܡܫܠܡܢܘܬܐ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܫܢܝ person.alex ܠ-home ܒܓܒܐ ܠܢܣܝܢܐ."},
"ha_remote":{"title":"ܡܚܪܘܩܐ ܕܩܘܪܛܡܐ ܡܫܪܐ ܩܗܘܐ","desc":"ܡܨܝܬ ܠܥܒܕܐ ܕ-Home Assistant. ܟܕ ܩܘܪܛܡܐ 'on' ܕܡܚܪܘܩܐ ܕܒܝܬ ܐܦܝܐ ܡܬܕܪܫ, ܦܬܚ ܡܢܐ ܕܩܗܘܐ ܘܫܒܩ ܡܠܬܐ; ܩܘܪܛܡܐ 'off' ܡܥܒܪ ܠܗ. ܡܬܙܝܥ ܡܚܕܐ, ܕܠܐ ܫܘܐܠܐ ܬܕܝܪܐ. ܕܘܫ 'ܪܗܛ' ܠܢܣܝܢܐ ܥܡ ܩܘܪܛܡܐ ܕܟܬܒܬ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܐܘ ܥܒܕ ܩܠܝܕܐ ܝܡܝܢܐ ܥܠ ܠܒܢܬܐ ܕ'ܟܕ ܥܒܕܐ ܕ-Home Assistant' ܘܓܒܝ 'ܪܗܛ ܗܕܐ ܦܣܩܬܐ' ܠܢܣܝܢܐ ܕܝܫܬܐ ܕܛܘܦܣܐ. ܫܢܝ 'kitchen remote' ܠܫܡܐ ܕܡܚܪܘܩܟ, ܘ-zha_event ܠ-deconz_event ܐܘ ܠ-hue_event ܐܢ ܗܢܐ ܗܘ ܕܡܫܕܪ ܡܚܪܘܩܟ (Developer tools → Events ܒ-Home Assistant ܡܚܘܐ ܠܗܘܢ)."},
"ha_holiday":{"title":"ܫܪܓܐ ܕܚܓܐ","desc":"ܟܘܠ ܪܡܫܐ ܟܕ ܒܐܘܪܚܐ ܐܢܬ, Claude ܓܒܐ ܫܪܓܐ ܠܡܦܛܚ, ܐܟ ܕܗܘܐ ܒܝܬܐ ܡܫܬܡܫ ܫܪܝܪܐܝܬ ܒܫܒܘܥܐ ܕܥܒܪ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܒܠܚܘܕ ܫܪܓܐ ܡܬܓܒܝܢ: ܛܘܟܣܐ ܒܚܢ ܕܟܘܠ ܐܝܕܐ ܫܪܐ ܒ'light.'."},
"ha_weekly":{"title":"ܡܚܘܝܢܘܬܐ ܫܒܘܥܝܬܐ ܕܒܝܬܐ","desc":"ܒܪܡܫܐ ܕܚܕ ܒܫܒܐ: ܚܝܠܐ, ܚܘܡܐ, ܫܪܒܐ ܕܚܝܠܐ ܘܟܘܠ ܡܕܡ ܢܘܟܪܝܐ, ܐܟ ܡܚܘܝܢܘܬܐ ܙܥܘܪܬܐ ܕܢܛܪܐ ܒܦܢܓܐ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܕܘܫ 'ܪܗܛ' ܒܟܘܠ ܝܘܡ ܠܡܚܙܐ ܡܚܘܝܢܘܬܐ ܕܗܢܐ ܫܒܘܥܐ ܗܫܐ."},
"ha_private":{"title":"ܡܟܡܘܬܐ ܟܣܝܬܐ, ܕܢܛܪܐ ܒܝܬܐ","desc":"ܕܡܘܬܐ ܕ-Llama ܒܚܫܘܒܟ ܩܪܐ ܟܘܠܝܗ ܒܝܬܐ ܘܟܬܒ ܡܟܡܘܬܐ, ܘܡܢܝܢܐ ܕܒܝܬܟ ܠܥܠܡ ܠܐ ܢܦܩܝܢ ܡܢ ܒܝܬܐ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܪܗܛ ܠܗ ܥܠ ܚܫܘܒܐ ܕ-Ollama, ܠܘܬ Home Assistant."},
"ha_ask":{"title":"ܫܐܠ ܠܒܝܬܐ","desc":"ܫܐܠ ܟܘܠ ܡܕܡ ('ܐܝܬ ܐܢܫ ܒܝܬܐ?', 'ܫܒܩܬ ܬܢܘܪܐ ܦܩܝܚܐ?'). Claude ܥܢܐ ܒܠܚܘܕ ܥܡ ܡܢܝܢܐ ܕ-Home Assistant ܕܝܠܟ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"Claude ܐܡܪ ܐܢ ܡܢܝܢܐ ܠܐ ܐܚܕܝܢ ܦܬܓܡܐ."},
"ha_bins":{"title":"ܥܘܗܕܢܐ ܕܝܘܡܐ ܕܛܢܦܘܬܐ","desc":"ܒ-19:00, ܒܚܢ ܐܢ ܡܢܐ ܕܛܢܦܘܬܐ ܢܦܩܝܢ ܠܡܚܪ (ܥܡ ܫܘܚܠܦܐ ܕܥܐܕܐ) ܘܡܥܗܕ ܠܟ ܐܝܢܐ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܐܪܡܝ ܠܗ ܠܪܓܝܫܐ ܕܡܟܢܫܢܘܬܐ ܕܛܢܦܘܬܐ ܕܝܠܟ."},
"ha_doorbell":{"title":"ܡܢ ܒܬܪܥܐ?","desc":"ܟܕ ܙܓܐ ܕܬܪܥܐ ܩܥܐ, Claude ܚܙܐ ܒܩܡܝܪܐ ܘܐܡܪ ܠܟ ܡܢ ܐܘ ܡܢܐ ܬܡܢ, ܐܦ ܡܫܠܡܢܘܬܐ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܒܓܒܐ, ܫܢܝ binary_sensor.doorbell ܠ-on ܠܡܩܥܝܘ."},
"ha_parcel":{"title":"ܡܫܠܡܢܘܬܐ ܫܒܝܩܐ ܠܒܪ?","desc":"ܒ-18:00, ܚܙܐ ܒܩܡܝܪܐ ܕܬܪܥܐ ܩܕܡܝܐ ܘܡܥܗܕ ܠܟ ܐܢ ܡܫܠܡܢܘܬܐ ܥܕܟܝܠ ܝܬܝܒܐ ܥܠ ܕܪܓܐ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܫܢܝ ܫܥܬܐ ܠܙܒܢܐ ܕܒܥܝܕܐ ܐܬܐ ܐܢܬ ܠܒܝܬܐ."},
"ha_motion":{"title":"ܙܘܗܪܐ ܚܟܝܡܐ ܕܙܘܥܐ","desc":"ܟܕ ܩܡܝܪܐ ܕܓܢܬܐ ܚܙܝܐ ܙܘܥܐ, Claude ܒܚܢ ܨܘܪܬܐ ܘܡܙܗܪ ܠܟ ܒܠܚܘܕ ܥܠ ܐܢܫܐ ܐܘ ܪܟܫܐ, ܠܐ ܥܠ ܫܘܢܪܐ ܐܘ ܐܝܠܢܐ ܕܡܬܙܝܥܝܢ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܫܢܝ binary_sensor.motion_garden ܠ-off ܘܒܬܪ ܠ-on ܒܓܒܐ."},
"ha_car":{"title":"ܗܢܐ ܪܟܫܢ ܗܘ?","desc":"ܟܕ ܡܕܡ ܙܥ ܥܠ ܐܘܪܚܐ, Claude ܡܦܫܩ ܪܟܫܐ ܘܚܫܒ ܠܗ ܥܡ ܗܘ ܕܥܗܕ ܐܟ ܕܝܠܟ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܪܗܛܐ ܩܕܡܝܐ ܥܗܕ ܪܟܫܟ; ܪܗܛܐ ܕܒܬܪܝܗ ܚܫܒܝܢ ܥܡܗ."},
"ha_garage":{"title":"ܒܝܬ ܪܟܫܐ ܫܪܝܪܐܝܬ ܐܚܝܕ?","desc":"ܒ-22:00, ܚܫܒ ܪܓܝܫܐ ܕܬܪܥܐ ܕܒܝܬ ܪܟܫܐ ܥܡ ܡܐ ܕܩܡܝܪܐ ܡܚܘܝܐ, ܘܡܙܗܪ ܠܟ ܐܢ ܠܐ ܫܘܝܢ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܛܒ ܠܬܪܥܐ ܕܪܓܝܫܝܗܘܢ ܙܒܢܝܢ ܡܬܥܟܠܝܢ."},
"ha_overnight":{"title":"ܟܢܫܐ ܕܠܝܠܝܐ","desc":"ܒ-07:00, ܡܟܡܘܬܐ ܚܕܐ ܢܝܚܬܐ ܕܟܘܠ ܡܐ ܕܬܪܥܐ ܘܪܓܝܫܐ ܕܙܘܥܐ ܐܪܓܫܘ ܒܠܝܠܝܐ, ܚܠܦ ܟܢܘܫܝܐ ܕܙܘܗܪܐ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܐܘܣܦ ܪܓܝܫܐ ܐܚܪܢܐ ܠܫܐܠܬܐ."},
"ha_newdevice":{"title":"ܐܘܪܓܢܐ ܚܕܬ ܒܪܫܬܐ","desc":"ܟܕ ܐܘܪܓܢܐ ܠܐ ܝܕܝܥܐ ܥܐܠ ܠܪܫܬܐ, Claude ܡܦܫܩ ܡܢܐ ܡܬܣܒܪ ܕܢܗܘܐ ܘܡܢܐ ܠܡܒܚܢ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܡܫܬܡܫܐ ܒܪܓܝܫܐ ܕܡܫܡܫܢܐ ܚܕܬ ܕ-UniFi; ܫܢܝ ܠܗ ܠܕܝܠܟ."},
"ha_cheap":{"title":"ܪܗܛ ܐܘܪܓܢܐ ܟܕ ܚܝܠܐ ܙܥܘܪ ܛܝܡܐ","desc":"ܨܒܪ ܐܡܬ ܠܡܪܗܛ ܡܫܝܓܐ ܕܡܢܐ, ܡܢܐ ܕܚܘܪܐ ܘܡܛܥܢܢܐ ܕܪܟܫܐ, ܡܢ ܛܝܡܐ, ܙܒܢܐ ܙܥܘܪ ܛܝܡܐ ܘܣܒܪܐ ܕܫܡܫܐ, ܥܡ ܥܠܬܐ ܠܟܘܠ ܚܕ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܐܘܣܦ ܐܘܪܓܢܝܟ ܠܫܐܠܬܐ."},
"ha_bill":{"title":"ܠܡܢܐ ܝܩܝܪ ܗܘܐ ܐܬܡܠ?","desc":"ܚܫܒ ܬܫܡܫܬܐ ܕܚܝܠܐ ܥܡ ܐܐܪ ܘܡܢ ܗܘܐ ܒܝܬܐ, ܘܡܦܫܩ ܒܡܠܐ ܦܫܝܛܬܐ ܠܡܢܐ ܥܠܬ ܐܘ ܢܗܬܬ. ܒܕܦܐ ܡܫܬܡܫܐ ܒܝܬܐ ܕܛܘܦܣܐ, ܒ-Python ܕܢܦܩܐ ܒ-Home Assistant ܕܝܠܟ ܫܪܝܪܐ.","tip":"ܫܐܠ ܠܗ ܟܘܠ ܨܦܪܐ ܠܫܒܘܥܐ ܠܡܫܟܚ ܥܝܕܐ."},
