"Stopped after starting {max_scripts} scripts. A message may be broadcasting itself in a loop.":"psaq bātar dšrā {max_scripts} psaqātā. melltā meškḥā dmšaddrā lnapšāh bḥdārā.",
"Stopped after {max_ai_calls} model calls in one run, to protect your usage.":"psaq bātar {max_ai_calls} qeryānē ddmwātā brahṭā ḥad, lnāṭrutā dmšammšānutāk.",
"Stopped after {max_steps} steps. A loop may never end; check repeat and while blocks.":"psaq bātar {max_steps} dargē. ḥdārā meškaḥ dlā nešlam; bḥan lebnē d'tnī' wd'kmā d'.",
"Stopped · 1 model call":"psaq · qeryānā ḥad ddmutā",
"Stopped · {n} model calls":"psaq · {n} qeryānē ddmwātā",
"Stopped: a model this run has already used has no known price, so it can't be held to its budget of {x}. Use models with a price, or a budget in tokens.":"psaq: dmutā dhānā rahṭā ꜣeštammaš bāh lēt lāh ṭīmā ydīꜥā, wmettul hānā lā meškḥā dtetꜣaḥḥad bḥušbāneh d{x}. ꜣeṭꜥan dmwātā ꜥam ṭīmā, ꜣaw ḥušbānā bꜣātwātā.",
"Stopped: the {window} allowance of {amount} for this {service} key has been reached ({spent} spent). It resets at {when}.":"psaq: šubqānā d{window} d{amount} lhānā qlīdā d{service} maṭṭā (npaq {spent}). methaddat b{when}.",
"Stopped: this run has spent {x} at list prices, which reaches its budget of {x2}. Raise the amount in the 'limit this run' block (or budget_dollars in second-thought.ini).":"psaq: hānā rahṭā npaq {x} bṭīmē ddmwātā, dmaṭṭē lḥušbāneh d{x2}. ꜣarīm menyānā blebntā d'taḥḥem lhānā rahṭā' (ꜣaw budget_dollars bsecond-thought.ini).",
"Stopped: this run has used {x} tokens, which reaches its budget of {x2}. Raise the number in the 'limit this run' block (or budget in second-thought.ini).":"psaq: hānā rahṭā ꜣeštammaš b{x} ꜣātwātā, dmaṭṭē lḥušbāneh d{x2}. ꜣarīm menyānā blebntā d'taḥḥem lhānā rahṭā' (ꜣaw budget bsecond-thought.ini).",
"Stopped: this {service} key has spent {spent} this month, which reaches the {plan} plan's monthly cap of {cap}. {service} stops taking calls there until {when}.":"psaq: hānā qlīdā d{service} npaq {spent} bhānā yarḥā, dmaṭṭē ltḥumā yarḥāyā d{cap} dqeyāmā {plan}. {service} lā mqabbel qeryānē tammān ꜥdammā l{when}.",
"Stopped: {model} has no known price, so its spending can't be counted against this key's allowances. Use a model with a price.":"psaq: {model} lēt lāh ṭīmā ydīꜥā, wmettul hānā npaqtāh lā meškḥā dtetmnē lwāt nāmosē dhānā qlīdā. ꜣeṭꜥan dmutā ꜥam ṭīmā.",
"Stopped: {model} has no known price, so this run can't be held to its budget of {x}. Use a model with a price, or a budget in tokens.":"psaq: {model} lēt lāh ṭīmā ydīꜥā, wmettul hānā hānā rahṭā lā meškaḥ dnetꜣaḥḥad bḥušbāneh d{x}. ꜣeṭꜥan dmutā ꜥam ṭīmā, ꜣaw ḥušbānā bꜣātwātā.",
