"That address isn't a news feed (RSS or Atom).":"hāy ꜥelqtā lā hwāt mabbꜥā dšmaꜥtā (RSS ꜣaw Atom).",
"That address isn't a web page or text ({x}).":"hāy ꜥelqtā lā hwāt dappā dreštā ꜣaw ktābā ({x}).",
