"That {kind} couldn't be read ({name}: {e}). It may be damaged, locked, or not really a {kind}.":"hānā {kind} lā meškaḥ dnetqrē ({name}: {e}). meškaḥ dḥbīl, ꜣaḥīd, ꜣaw lā šarrīrāꜣīt {kind}.",
"The 'ask Claude about picture' block has no question.":"lebntā d'šꜣal lClaude ꜥal ṣurtā' lēt lāh šeꜣltā.",
"The 'ask Claude for a record' block has no request.":"lebntā d'šꜣal lClaude ṭablā' lēt lāh bāꜥutā.",
"The 'change picture' block has no change in it.":"lebntā d'šannī ṣurtā' lēt lāh šuḥlāpā.",
"The 'chat' block has no message.":"lebntā d'mamllā' lēt lāh melltā.",
"The 'draw a picture' block has no description.":"lebntā d'ṣur ṣurtā' lēt lāh pušāqā.",
"The 'notify' block has no message.":"lebntā d'mawdaꜥ' lēt lāh melltā.",
"The 'rework the draft' block has no instruction.":"lebntā d'ꜥbed tub rušmā' lēt lāh puqdānā.",
"The 'save checkpoint' block needs a name.":"lebntā d'nṭor tḥumā' sānyā šmā.",
"The 'say' block has nothing to say.":"lebntā d'ꜣemar' lēt lāh meddem lmēmar.",
"The 'search the web' block is empty.":"lebntā d'bꜥī breštā' sraqtā.",
"The 'set {key} of' block needs a record in its middle slot.":"lebntā d'sīm {key} d' sānyā ṭablā bꜣatrāh dmeṣꜥāyā.",
"The 'set … of record' block needs a field name.":"lebntā d'sīm … dṭablā' sānyā šmā dḥaqlā.",
"The '{where}' block needs a picture in its picture slot.":"lebntā d'{where}' sānyā ṣurtā bꜣatrā dṣurtā.",
"The Llama server doesn't have model {model}. Run:  ollama pull {model}":"mšammšānā dLlama lēt leh dmutā {model}. rhaṭ:  ollama pull {model}",
"The MQTT broker at {host}:{port} didn't answer.":"mšammšānā dMQTT b{host}:{port} lā ꜥnā.",
"The MQTT broker at {host}:{port} refused the connection ({rc}). Check MQTT_USERNAME and MQTT_PASSWORD.":"mšammšānā dMQTT b{host}:{port} lꜥez lꜥelqtā ({rc}). bḥan MQTT_USERNAME wMQTT_PASSWORD.",
"The agent block needs a goal.":"lebntā dšlīḥā sānyā nīšā.",
"The agent only reads public web pages and feeds, not addresses on your own network (local_pages = yes allows them).":"šlīḥā qārē balḥod dappē gaḥyē dreštā wmabbꜥē, lā ꜥelqātā dꜥal rešttā dīlāk (local_pages = yes šābeq lhēn).",
"The agent's MCP server “{x}” isn't set up. Put {key} = <the command that starts it, or its https:// address> {where_keys}.":"mšammšānā dMCP dšlīḥā “{x}” lā ꜣeṭṭayyab. sīm {key} = <puqdānā dmšarē leh, ꜣaw ꜥelqtā dīleh dhttps://> {where_keys}.",
"The answer cites addresses this run never read, so check them before relying on it: {addresses}":"petgāmā maytē ꜥelqātā dhānā rahṭā lꜥālam lā qrā, wmettul hānā bḥan lhon qdām dtetṭkel ꜥlāwhy: {addresses}",
"The block '{kind}' can't run outside the block editor.":"lebntā '{kind}' lā meškḥā dterheṭ lbar men msadrānā dlebnē.",
"The calendar needs CALENDAR_URL {where_keys}: your calendar's private iCal address.":"qalandārā sānē CALENDAR_URL {where_keys}: ꜥelqtā ksītā diCal dqalandārāk.",
"The data for {service} isn't valid JSON. Use something like {\"temperature\": 20}.":"menyānē d{service} lā JSON šarrīrā. ꜣeṭꜥan meddem ꜣak {\"temperature\": 20}.",
"The downloaded runtime doesn't match its SHA-256, so it wasn't used. Nothing was changed.":"ṭuksā drahṭā dꜣetšqel lā šāwē lSHA-256 dīleh, wmettul hānā lā ꜣeštammaš. meddem lā ꜣeštaḥlap.",
"The downloaded runtime isn't a {latest} runtime, so it wasn't used. Nothing was changed.":"ṭuksā drahṭā dꜣetšqel lā hwā ṭuksā drahṭā d{latest}, wmettul hānā lā ꜣeštammaš. meddem lā ꜣeštaḥlap.",
"The email couldn't be sent ({e}).":"ꜣeggartā lā meškḥā dteštaddar ({e}).",
"The email server refused the login ({e}). Check EMAIL_PASSWORD is an app password.":"mšammšānā dꜣeggrātā lꜥez lmꜥālā ({e}). bḥan dEMAIL_PASSWORD melltā dkessyā dšuꜥālā hī.",
"The file changed, so it asks to be allowed again before its next run.":"pengā ꜣeštaḥlap, wmettul hānā šāꜣel dnešbqūn leh tub qdām rahṭā dātē.",
"The last run stopped part-way, after 1 saved step.":"rahṭā ḥrāyā psaq bpalgeh, bātar dargā ḥdā nṭīrtā.",
"The last run stopped part-way, after {n} saved steps.":"rahṭā ḥrāyā psaq bpalgeh, bātar {n} dargē nṭīrān.",
"The program “{name}” runs itself ({x}), which would never end.":"ṭuksā “{name}” rāheṭ lnapšeh ({x}), dlꜥālam lā nešlam.",
"The reply didn't have the expected shape: {bad}.":"lpetgāmā lā hwā ꜣeskēmā dmetsakkē: {bad}.",
"The reply reached the length limit, so the model was asked to carry on from where it stopped.":"petgāmā maṭṭā ltḥumā dꜣurkā, wmettul hānā ꜣetbꜥī men dmutā dtēzal men ꜣaykā dpesqat.",
"The reply wasn't readable JSON, so this step was wasted.":"petgāmā lā hwā JSON dmetqrē, wmettul hānā hādē dargā ꜣetabdat.",
"The review raised the same problems after two revisions, so revising can't fix them. The program may need something it wasn't given, such as a web page, a file or a fact: give it that (in the task, say, or through an agent that can read web pages), then run again.":"buḥrānā ꜣarīm hālēn mḥaššlātā bātar trēn tuqqānē, wmettul hānā tuqqānā lā meškaḥ dnetqnēn. ṭuksā meškaḥ dsānē meddem dlā ꜣetyheb leh, ꜣak dappā dreštā, pengā ꜣaw ṣebwā: hab leh (bꜥbādā, ꜣaw bšlīḥā dmeškaḥ dneqrē dappē dreštā), wbātar rhaṭ tub.",
"The run stopped.":"rahṭā psaq.",
"The run took longer than {x} seconds (max_seconds in second-thought.ini), so it stopped.":"rahṭā nged yattīr men {x} rpēpē (max_seconds bsecond-thought.ini), wmettul hānā psaq.",
"The task is empty. Type what you want into 'set task to'.":"ꜥbādā sraq. ktob mā dṣābē ꜣnt b'sīm ꜥbādā'.",
"The task names a web address, but this step can't open it. Tick 'using the web' on the block, or put the page's words in the task.":"ꜥbādā mšammē ꜥelqtā dreštā, ꜣellā hādē dargā lā meškḥā dteptaḥ lāh. ršum 'breštā' ꜥal lebntā, ꜣaw sīm mellē ddappā bꜥbādā.",
"The test case has no answer for this step ({what}). Save it again from a run that gets this far.":"nesyānā lēt leh petgāmā lhādē dargā ({what}). nṭor leh tub men rahṭā dmaṭṭē ꜥdammā lhārkā.",
"The tool block for “{block_name}” gives a type for “{name}”, but that My Block's inputs are: {x}.":"lebntā dmānā d“{block_name}” yāhbā gensā l“{name}”, ꜣellā mꜥālē dhāy lebntī ꜣennon: {x}.",
"The {x} couldn't be reached: {x2}":"{x} lā ꜣetmṭā: {x2}",
"The {x} couldn't be started ({x2} = {command}): {e}":"{x} lā meškaḥ dnešrē ({x2} = {command}): {e}",
"The {x} didn't answer when asked for its tools.":"{x} lā ꜥnā kad ꜣetšꜣel ꜥal mānāw.",
"The {x} didn't answer.":"{x} lā ꜥnā.",
"The {x} didn't reply to {method}.":"{x} lā ꜥnā l{method}.",
"The {x} gave a kind of result this runtime doesn't know (“{kind}”).":"{x} yheb gensā dpērā dhānā ṭuksā drahṭā lā yādaꜥ (“{kind}”).",
"The {x} looks like it uses MCP's old HTTP+SSE way of connecting, which Second Thought doesn't speak. Check the address, or use a newer server.":"{x} metḥzē dmeštamšā bꜣurḥā ꜥattīqtā dMCP dHTTP+SSE, dSecond Thought lā mmallel bāh. bḥan ꜥelqtā, ꜣaw ꜣeṭꜥan mšammšānā ḥdat yattīr.",
"The {x} refused the request ({status}). Check {x2}_TOKEN {where_keys}.":"{x} lꜥez lbāꜥutā ({status}). bḥan {x2}_TOKEN {where_keys}.",
"The {x} sent a reply that isn't JSON.":"{x} šaddar petgāmā dlā JSON.",
"The {x} speaks MCP {x2} this runtime doesn't. A newer Second Thought may.":"{x} mmallel MCP {x2} dhānā ṭuksā drahṭā lā. Second Thought ḥdat yattīr meškaḥ.",
"The {x} stopped{x2} Check {x3} {where_keys}.":"{x} psaq{x2} bḥan {x3} {where_keys}.",
