"COLLAPSE_ALL":"ܟܦܘܠ ܠܒܢܐ",
"COLLAPSE_BLOCK":"ܟܦܘܠ ܠܒܢܬܐ",
"CONTROLS_FLOW_STATEMENTS_OPERATOR_BREAK":"ܦܘܩ ܡܢ ܚܕܪܐ",
